static int p2d89_emit_lines_curves(P2D89_ShapeId id,const P2D89_Provider *p){if(id==P2D89_SHAPE_QUADRATIC_CURVE){if(!p2d89_i_move(p,-16384,8192))return 0;return p2d89_i_quad(p,0,-16384,16384,8192);}if(id==P2D89_SHAPE_CUBIC_CURVE){if(!p2d89_i_move(p,-16384,8192))return 0;return p2d89_i_cubic(p,-8192,-16384,8192,-16384,16384,8192);}if(id==P2D89_SHAPE_S_CURVE){if(!p2d89_i_move(p,-16384,-8192))return 0;return p2d89_i_cubic(p,-4096,-16384,4096,16384,16384,8192);}if(id==P2D89_SHAPE_WAVE){if(!p2d89_i_move(p,-16384,0))return 0;if(!p2d89_i_cubic(p,-12288,-8192,-4096,-8192,0,0))return 0;return p2d89_i_cubic(p,4096,8192,12288,8192,16384,0);}if(id==P2D89_SHAPE_ARC){if(!p2d89_i_move(p,-16384,8192))return 0;return p2d89_i_cubic(p,-8192,-12288,8192,-12288,16384,8192);}if(id==P2D89_SHAPE_SEMICIRCLE_ARC)return p2d89_i_semicircle(0,p);if(id==P2D89_SHAPE_QUARTER_ARC)return p2d89_i_quarter_circle(0,p);if(id==P2D89_SHAPE_THREE_QUARTER_ARC)return p2d89_i_arc_3q(p);if(id==P2D89_SHAPE_SPIRAL)return p2d89_emit_spiral(768U,48U,p);return 0;}
const P2D89_Submodule p2d89_submodule_lines_curves = { { P2D89_MODULE_LINES, "lines", "curves", (unsigned int)(sizeof(shapes)/sizeof(shapes[0])) }, shapes, p2d89_emit_lines_curves };
